(function(){const ARTICLE="https://www.facebook.com/help/162586890471598";const isApple=()=>/iphone|ipad|ipod/i.test(navigator.userAgent||"")||/Macintosh/.test(navigator.userAgent||"")&&navigator.maxTouchPoints>1;const linkFor=device=>{const platform=device==="pc"?"www":device==="tablet"?isApple()?"ipad-app":"android-app":isApple()?"iphone-app":"android-app";return ARTICLE+"?helpref=platform_switcher&cms_platform="+platform};let dialog=null;let opener=null;function close(){if(!dialog)return;dialog.remove();dialog=null;document.removeEventListener("keydown",onKey);if(opener)opener.focus()}function onKey(e){if(e.key==="Escape"||e.key==="Esc"){e.preventDefault();close();return}if(e.key!=="Tab"||!dialog)return;const els=dialog.querySelectorAll("a, button");const first=els[0];const last=els[els.length-1];if(e.shiftKey&&document.activeElement===first){e.preventDefault();last.focus()}else if(!e.shiftKey&&document.activeElement===last){e.preventDefault();first.focus()}}function open(btn){close();opener=btn;dialog=document.createElement("div");dialog.className="fbh-back";dialog.innerHTML='<div class="fbh-box" role="dialog" aria-modal="true" aria-labelledby="fbh-title">'+'<button type="button" class="fbh-close" aria-label="Close">×</button>'+'<h2 id="fbh-title" class="fbh-title">I am using...</h2>'+'<p class="fbh-note">Opens Facebook\'s help in a new tab.</p>'+'<div class="fbh-options">'+[["mobile","Mobile"],["tablet","Tablet"],["pc","PC"]].map(([k,label])=>'<a class="fbh-option" data-device="'+k+'" href="'+linkFor(k)+'" target="_blank" rel="noopener noreferrer">'+label+'<span aria-hidden="true">↗</span><span class="sr-only"> (opens in a new tab)</span></a>').join("")+"</div></div>";dialog.addEventListener("click",e=>{if(e.target===dialog||e.target.closest(".fbh-close"))close();else if(e.target.closest(".fbh-option"))setTimeout(close,0)});document.body.appendChild(dialog);document.addEventListener("keydown",onKey);dialog.querySelector(".fbh-option").focus()}document.addEventListener("click",e=>{const btn=e.target.closest("[data-fb-help]");if(!btn)return;e.preventDefault();open(btn)})})();